/**
 * Phase 37b: the headline totals for the verify scripts, from src/tests/fixtures/headlines.json (regenerated by
 * scripts/pinHeadlines.mjs; src/tests/utils/headlines.ts). `headlineTotal('fa')` → "21:07.7".
 * Names: fa, toa, cox, tob (Team defaults), faSolo (FA Solo, party 1), faNotOwned (FA without Obligator / Ascension).
 */
import { readFileSync } from 'node:fs';

export const HEADLINES = JSON.parse(readFileSync(new URL('../src/tests/fixtures/headlines.json', import.meta.url), 'utf8')).plans;

export const headlineTotal = (name) => {
  const h = HEADLINES[name];
  if (!h) throw new Error(`no headline "${name}" in src/tests/fixtures/headlines.json`);
  return h.total;
};
